package com.revivex.service; import com.revivex.domain.*; import org.springframework.stereotype.Component; import java.math.BigDecimal; @Component("demoExecution") public class DemoExecutionAdapter implements RecoveryExecutionAdapter { public ExecutionResult execute(RecoveryCase c,RecoveryAction a){BigDecimal recovered=c.getPayment().getAmount().multiply(BigDecimal.valueOf(c.getRecoveryProbability())).setScale(2,java.math.RoundingMode.HALF_UP);return new ExecutionResult("RECOVERED","DEMO-"+a.getIdempotencyKey(),null,recovered,"Deterministic synthetic outcome; no real payment executed.");} public ExecutionResult reconcile(RecoveryAction a){return new ExecutionResult(a.getStatus(),a.getProviderReference(),a.getShortUrl(),a.getActualRecovered(),"Demo action already reconciled.");} public String mode(){return "demo";} }
